DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PGchoicemacros.pl",
  "contextForm.pl",
  "contextFraction.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

Context("Fraction");
Context()->operators->remove("U");
Context()->noreduce('(-x)+y','(-x)-y');
@orig_vars = random_subset(2, 'a'..'n','p'..'z','A'..'D', 'F'..'N','P'..'Z');
$dbldvar = $orig_vars[0];
@vars = ($dbldvar, @orig_vars);
Context()->variables->are();
for my $i (1,2) {
  Context()->variables->add($orig_vars[$i-1] => 'Real');
}
@fracs = ();
for my $j (2..10) {
  for my $i (1..10) {
    push(@fracs, Fraction($i,$j));
  }
}
@signs = (1,list_random(-1,1),list_random(-1,1));
@signs = (@signs)[NchooseK(3,3)];
@coefs = (@fracs)[NchooseK(90,3)];
@coefs = map {$signs[$_-1]*$coefs[$_-1]} (1..3);
$coefsum = $coefs[0] + $coefs[1];
@terms = ();
for my $i (1..3) {
  push(@terms, Formula("$coefs[$i-1]*$vars[$i-1]"));
}
@terms = random_subset(3,@terms);
$sum = Formula(join('+', @terms))->reduce;

%combinedcoefs = ();
$combinedcoefs{$orig_vars[0]} = Fraction($sum->eval($orig_vars[0] => 1, $orig_vars[1] => 0));
$combinedcoefs{$orig_vars[1]} = Fraction($sum->eval($orig_vars[0] => 0, $orig_vars[1] => 1));
$ans = Formula("$combinedcoefs{$orig_vars[0]} $orig_vars[0] + $combinedcoefs{$orig_vars[1]} $orig_vars[1]")->reduce;

Context("Form");
Context()->operators->remove("U");
Context()->variables->are();
for my $i (1,2) {
  Context()->variables->add($orig_vars[$i-1] => 'Real');
}
$ans = Formula("$ans");

#############################
# Exercise Group Introduction
#############################

BEGIN_PGML
Simplify the expression by combining like terms if possible.

END_PGML

######
# Body
######

BEGIN_PGML
[`[$sum]`]

[_]{$ans}{20}

END_PGML

##########
# Solution
##########

BEGIN_PGML_SOLUTION
There are two [`[$dbldvar]`]-terms. Their coefficients are [`[$coefs[0]]`] and [`[$coefs[1]]\text{.}`] We can add those two terms by adding their coefficients to get [`[$coefsum]\text{.}`] So the expression simplifies to [`[$ans]\text{.}`]

END_PGML_SOLUTION

#############
# End Problem
#############

ENDDOCUMENT();
